-- Checklist: projetista responsável dos clientes já agendados, conforme a agenda do sistema interno (05/10/2026).
-- Casamento pelo nº da venda. Só preenche quem ainda não tem projetista. Giovanni entra na lista de projetistas.
update public.config set checklist_agenda = jsonb_set(checklist_agenda, '{projetistas}', checklist_agenda->'projetistas' || '["Giovanni"]'::jsonb)
 where id = 1 and not (checklist_agenda->'projetistas' ? 'Giovanni');
